interface ScenarioResult {
  results: Array<{ premium: number } | { payout: number; remainingCap: number }>;
}

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

export function processScenario(input: any): ScenarioResult {
  const results = input.steps.map((step: any) => {
    const basePremium = step.items.reduce(
      (sum: number, item: any) => sum + (BASE_PREMIUMS[item.type] ?? 0),
      0,
    );
    return { premium: basePremium + PROCESSING_FEE };
  });
  return { results };
}

