import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  function quoteItems(items: Array<Record<string, unknown>>, yearsWithMHPCO = 0) {
    return processScenario({
      customer: { yearsWithMHPCO },
      steps: [{ op: "quote" as const, items }],
    });
  }

  describe("Quote - base premiums", () => {
    it("should return 5G for an empty item list (processing fee only)", () => {
      expect(quoteItems([]).results[0]).toEqual({ premium: 5 });
    });
    it("should return base premium + fee for a single sword (100 + 5 = 105)", () => {
      expect(quoteItems([{ type: "sword" }]).results[0]).toEqual({ premium: 105 });
    });
    it("should return base premium + fee for each main item type (amulet, staff, potion)", () => {
      expect(quoteItems([{ type: "amulet" }]).results[0]).toEqual({ premium: 65 });
      expect(quoteItems([{ type: "staff" }]).results[0]).toEqual({ premium: 85 });
      expect(quoteItems([{ type: "potion" }]).results[0]).toEqual({ premium: 45 });
    });
    it("should return 25G base premium per component (rune or moonstone)", () => {
      expect(quoteItems([{ type: "rune" }]).results[0]).toEqual({ premium: 30 });
      expect(quoteItems([{ type: "moonstone" }]).results[0]).toEqual({ premium: 30 });
      expect(quoteItems([{ type: "rune" }, { type: "rune" }]).results[0]).toEqual({ premium: 55 });
    });
    it("should apply block discount for exactly 3 alike components (60G instead of 75G)", () => {
      const threeRunes = [{ type: "rune" }, { type: "rune" }, { type: "rune" }];
      expect(quoteItems(threeRunes).results[0]).toEqual({ premium: 65 });
    });
    it("should not apply block discount for non-exact-3 counts of alike components", () => {
      const runes = (n: number) => Array.from({ length: n }, () => ({ type: "rune" }));
      expect(quoteItems(runes(2)).results[0]).toEqual({ premium: 55 });
      expect(quoteItems(runes(4)).results[0]).toEqual({ premium: 105 });
      expect(quoteItems(runes(7)).results[0]).toEqual({ premium: 180 });
    });
    it("should treat different component types separately for block discount", () => {
      expect(quoteItems([
        { type: "rune" }, { type: "rune" }, { type: "moonstone" },
      ]).results[0]).toEqual({ premium: 80 });
      expect(quoteItems([
        { type: "rune" }, { type: "rune" }, { type: "rune" },
        { type: "moonstone" }, { type: "moonstone" }, { type: "moonstone" },
      ]).results[0]).toEqual({ premium: 125 });
    });
    it("should sum base premiums for multiple items in a policy", () => {
      expect(quoteItems([
        { type: "sword" }, { type: "amulet" },
      ]).results[0]).toEqual({ premium: 165 });
    });
  });

  describe("Quote - item-specific modifiers", () => {
    it("should add 50% cursed surcharge to the cursed item's base premium", () => {
      expect(quoteItems([
        { type: "sword", cursed: true },
      ]).results[0]).toEqual({ premium: 155 });
    });
    it.todo("should add 30% high-enchantment surcharge for enchantment >= 5");
    it.todo("should apply both cursed and high-enchantment surcharges to same item");
    it.todo("should apply item-specific modifiers only to affected item, not whole policy");
  });

  describe("Quote - policy-wide modifiers", () => {
    it.todo("should apply 20% loyalty discount for customer with >= 2 years");
    it.todo("should apply 10% first insurance surcharge on each quote");
    it.todo("should apply 15% follow-up discount on second and subsequent quotes");
    it.todo("should stack policy-wide modifiers (loyalty + first insurance + follow-up)");
  });

  describe("Quote - rounding", () => {
    it.todo("should round premiums up (in MHPCO's favor)");
  });

  describe("Claim - basic payout", () => {
    it.todo("should apply 100G deductible per damaged item");
    it.todo("should fully reimburse standard items minus deductible");
    it.todo("should reimburse at 50% for items with enchantment >= 8, then deductible");
    it.todo("should fully reimburse dragon-material items minus deductible");
    it.todo("should apply 50% when both dragon-material and enchantment >= 8");
    it.todo("should apply deductible per damaged item in multi-item damage");
  });

  describe("Claim - cap", () => {
    it.todo("should cap total payout at 2x insurance sum");
    it.todo("should track remaining cap across multiple claims on same policy");
  });

  describe("Claim - payout rounding", () => {
    it.todo("should round payouts down (in MHPCO's favor)");
  });

  describe("Error handling", () => {
    it.todo("should reject unknown item types in quote");
    it.todo("should reject damage for item not in policy");
    it.todo("should reject negative damage amounts");
    it.todo("should reject more damages of a type than insured items of that type");
  });
});

